import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long x = nextLong(), y = nextLong(), r = nextLong(), a = nextLong(), b = nextLong(), s = nextLong();
            long v = (x - a) * (x - a) + (y - b) * (y - b);
            long sum = (r + s) * (r + s), diff = (r - s) * (r - s);
            if (v == 0) out.append("Concentric");
            else if (v == sum || v == diff) out.append("Touching");
            else if (v > sum) out.append("Disjoint-Outside");
            else if (v < diff) out.append("Disjoint-Inside");
            else out.append("Intersecting");
            out.append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	n := int(nextInt())
	for i := 0; i < n; i++ {
		x, y, r, a, b, s := nextInt(), nextInt(), nextInt(), nextInt(), nextInt(), nextInt()
		v := (x-a)*(x-a) + (y-b)*(y-b)
		sum, diff := (r+s)*(r+s), (r-s)*(r-s)
		switch {
		case v == 0:
			w.WriteString("Concentric")
		case v == sum || v == diff:
			w.WriteString("Touching")
		case v > sum:
			w.WriteString("Disjoint-Outside")
		case v < diff:
			w.WriteString("Disjoint-Inside")
		default:
			w.WriteString("Intersecting")
		}
		w.WriteByte('\n')
	}
	_ = strconv.Itoa
}
